const badgeColors=[['#14834b','Green'],['#2563eb','Blue'],['#ea580c','Orange'],['#9333ea','Purple'],['#dc2626','Red'],['#0891b2','Cyan'],['#ca8a04','Gold'],['#db2777','Pink'],['#475569','Slate'],['#0f766e','Teal']];
