function expirySync(staff){if(!staff?.id)return;const taskKey='staff-expiry-'+staff.id;db.tasks=db.tasks.filter(t=>!(t.autoKey||'').startsWith(taskKey));if(!staff.expiryDate){save();return}const due=staff.expiryDate;const d=new Date(due+'T12:00:00');if(Number.isNaN(d.getTime()))return;d.setDate(d.getDate()-7);const prior=d.toISOString().slice(0,10);for(const [suffix,date,title] of [['-warning',prior,`Code / designation expiry in 7 days · ${staff.name} (${staff.code})`],['-due',due,`Renew staff code / designation · ${staff.name} (${staff.code})`]]){const key=taskKey+suffix;if(!db.tasks.some(t=>t.autoKey===key)){db.tasks.push({id:id(),autoKey:key,title,due:date,reminder:date+'T09:00',staff:staff.id,status:'Planned',note:`Expiry: ${due}. Verify renewal and update staff profile.`})}}save()}
