const now=()=>new Date().toISOString().slice(0,10), money=n=>'Rs. '+(Number(n)||0).toLocaleString('en-PK',{maximumFractionDigits:2});
// Completed tasks expire 30 full days after their recorded completion time.
// Existing completed tasks with no timestamp are dated from first use of this release (safe migration).
function cleanupCompletedTasks(){
 const stamp=new Date().toISOString(),cutoff=Date.now()-30*24*60*60*1000;
 let changed=false;
 db.tasks=db.tasks.filter(t=>{
  if(t.status==='Completed'){
   if(!t.completedAt){t.completedAt=stamp;changed=true}
   const ms=Date.parse(t.completedAt);
   if(Number.isFinite(ms)&&ms<=cutoff){changed=true;return false}
  }else if(t.completedAt){delete t.completedAt;changed=true}
  return true;
 });
 return changed;
}
function save() {
  cleanupCompletedTasks();

  try {
    localStorage.setItem(KEY, JSON.stringify(db));
  } catch (error) {
    alert('Local storage full. Export your backup.');
    return;
  }

  // Queue only new or modified tasks, not all old records.
  if (!window.NexuraTasksSync?.queueTask) return;

  const previous = JSON.parse(
    localStorage.getItem('nexura_tasks_sync_snapshot_v1') || '{}'
  );

  const next = { ...previous };

  for (const task of db.tasks) {
    const current = JSON.stringify(task);

    if (!(task.id in previous)) {
      // Remember existing tasks without uploading them.
      next[task.id] = current;
      continue;
    }

    if (previous[task.id] !== current) {
      window.NexuraTasksSync.queueTask(task);
      next[task.id] = current;
    }
  }

  localStorage.setItem(
    'nexura_tasks_sync_snapshot_v1',
    JSON.stringify(next)
  );
}
if(cleanupCompletedTasks())save();
function add(collection, fields) {
  const r = {
    id: id(),
    ...fields,
    createdAt: new Date().toISOString()
  };

  db[collection].push(r);
  save();

  if (collection === 'tasks' && window.NexuraTasksSync) {
    window.NexuraTasksSync.queueTask(r);
  }

  return r;
}
function update(collection, recordId, fields) {
  const r = db[collection].find(x => x.id === recordId);

  if (r) {
    const previous = r.status;

    Object.assign(r, fields);

    if (collection === 'tasks' && previous !== r.status) {
      if (r.status === 'Completed') {
        r.completedAt = new Date().toISOString();
      } else {
        delete r.completedAt;
      }
    }

    save();

    // Sync only task updates to Cloudflare D1.
    if (collection === 'tasks' && window.NexuraTasksSync) {
      window.NexuraTasksSync.queueTask(r);
    }
  }

  return r;
}
function get(c,i){return db[c].find(x=>x.id===i)}
function staffName(i){const r=get('staff',i);return r?`${r.name} (${r.code})`:'—'}
function clientName(i){return get('customers',i)?.name||'—'}
function option(value,label){return `<option value="${esc(value)}">${esc(label)}</option>`}
function staffOptions(filter=()=>true){return option('','Select staff')+db.staff.filter(filter).sort((a,b)=>Number(a.code)-Number(b.code)).map(s=>option(s.id,`${s.name} (${s.code}) · ${s.designation}`)).join('')}
function clientOptions(){return option('','Select customer')+db.customers.map(c=>option(c.id,`${c.name} · ${c.phone||''}`)).join('')}
function field(name,label,type='text',extra=''){const tel=type==='tel'?' inputmode="tel" pattern="\\+[1-9][0-9]{7,14}" title="Use international WhatsApp format, e.g. +923001234567" placeholder="+923001234567"':'';return `<div><label>${esc(label)}</label><input name="${esc(name)}" type="${type}" ${extra}${tel}></div>`}
function select(name,label,options,extra=''){return `<div><label>${esc(label)}</label><select name="${esc(name)}" ${extra}>${options}</select></div>`}
function note(name='note',label='NOTE'){return `<div class="wide"><label>${esc(label)}</label><textarea name="${esc(name)}" rows="2"></textarea></div>`}
function formData(f){return Object.fromEntries(new FormData(f).entries())}
// Binary attachments are stored in this browser's IndexedDB, not localStorage.
const fileDB=()=>new Promise((resolve,reject)=>{const req=indexedDB.open('nexura_v2_binary_attachments',1);req.onupgradeneeded=()=>req.result.createObjectStore('blobs',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
async function fileOperation(mode,id,record){const dbx=await fileDB();return new Promise((resolve,reject)=>{const tx=dbx.transaction('blobs',mode);const store=tx.objectStore('blobs');const req=mode==='readonly'?store.get(id):record===null?store.delete(id):store.put(record);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.oncomplete=()=>dbx.close()})}
async function storeAttachment(file){if(!file)return null;const fid=id();await fileOperation('readwrite',fid,{id:fid,name:file.name,type:file.type||'application/octet-stream',blob:file,createdAt:new Date().toISOString()});return fid}
async function readAttachment(fid){return fid?fileOperation('readonly',fid):null}
async function removeAttachment(fid){if(fid)await fileOperation('readwrite',fid,null)}
function attachmentControls(record,kind){const name=record.attachmentName||record.attachment||'';return `<div class="wide"><label>Attachment ${kind==='staff'?'(PDF only)':'(PDF or image)'}</label><input type="file" id="recordFile" accept="${kind==='staff'?'.pdf,application/pdf':'.pdf,application/pdf,image/*'}"><div class="muted" style="margin:7px 0">Existing: ${esc(name||'None')} · Files are stored locally in this browser.</div>${record.attachmentId?`<div class="row start"><button type="button" class="secondary small" data-file-action="preview">Preview</button><button type="button" class="secondary small" data-file-action="download">Download</button><button type="button" class="secondary small" data-file-action="share">Share</button><button type="button" class="secondary small" data-file-action="delete">Delete</button></div>`:''}<small class="muted">To replace, browse for a new file and save the record. Old file is deleted only after the new one is saved.</small></div>`}
function attachFileButtons(collection,recordId){document.querySelectorAll('[data-file-action]').forEach(b=>b.onclick=async()=>{const record=get(collection,recordId);if(!record?.attachmentId){alert('Save the record first.');return}const action=b.dataset.fileAction;try{if(action==='delete'){if(!confirm('Delete this attachment permanently from this browser?'))return;await removeAttachment(record.attachmentId);update(collection,recordId,{attachmentId:'',attachmentName:'',attachment:''});if(collection==='tasks')taskView(recordId);else if(collection==='customers')clientProfile(recordId);else staffProfile(recordId);return}const data=await readAttachment(record.attachmentId);if(!data?.blob){alert('Attachment file not found in this browser. A filename-only attachment from an older version must be uploaded again.');return}const blob=data.blob;if(action==='share'){const file=new File([blob],data.name,{type:data.type});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:data.name})}else{alert('Direct file sharing is unavailable in this browser. Download the file, then share it manually.')}return}const url=URL.createObjectURL(blob);if(action==='preview'){const w=window.open(url,'_blank');if(!w)alert('Allow pop-ups to preview this attachment.');setTimeout(()=>URL.revokeObjectURL(url),60000)}else{const a=document.createElement('a');a.href=url;a.download=data.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}}catch(e){if(e.name!=='AbortError')alert('Attachment error: '+e.message)}})}
async function saveRecordAttachment(collection,recordId,file){if(!file)return true;const old=get(collection,recordId);if(!old)return false;if(collection==='staff'&&file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){alert('Staff attachments must be PDF files.');return false}if((collection==='tasks'||collection==='customers')&&file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')&&!file.type.startsWith('image/')){alert('Choose a PDF or image.');return false}try{const fid=await storeAttachment(file);const previous=old.attachmentId;update(collection,recordId,{attachmentId:fid,attachmentName:file.name,attachment:file.name});if(previous){try{await removeAttachment(previous)}catch(e){console.warn('Old attachment cleanup failed',e)}}return true}catch(e){alert('File could not be stored: '+e.message);return false}}
function modal(title,html,onSubmit){$('#modalBody').innerHTML=`<div class="row"><h2>${esc(title)}</h2><button class="secondary small" id="closeModal">Close</button></div><form id="editForm">${html}<div class="row start"><button class="primary" type="submit">Save</button></div></form>`;$('#modal').classList.remove('hidden');$('#closeModal').onclick=closeModal;$('#editForm').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');button.disabled=true;try{const data=formData(form);if(await onSubmit(data,form)!==false){closeModal();render()}}catch(err){alert('Save failed: '+err.message)}finally{button.disabled=false}}}
function closeModal(){$('#modal').classList.add('hidden')}
function table(headers,records,renderRow){return `<div class="scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${records.length?records.map(renderRow).join(''):`<tr><td colspan="${headers.length}" class="empty">No records yet</td></tr>`}</tbody></table></div>`}
function csv(name,head,rows){const q=x=>'"'+String(x??'').replace(/"/g,'""')+'"';download(name+'.csv','\ufeff'+[head,...rows].map(a=>a.map(q).join(',')).join('\r\n'),'text/csv')}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500)}
function pdf(title,headers,rows){const w=window.open('','_blank');if(!w){alert('Allow popups to print or save as PDF');return}w.document.write(`<title>${esc(title)}</title><style>body{font:12px Arial;margin:25px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #bbb;padding:7px;text-align:left}@page{size:A4 landscape}</style><h2>NEXURA · ${esc(title)}</h2><p>${now()}</p>${table(headers,rows,r=>'<tr>'+r.map(x=>`<td>${esc(x)}</td>`).join('')+'</tr>')}`);w.document.close();setTimeout(()=>w.print(),350)}
