function bindExports(name,head,rows){$$(`[data-export="${name}"]`).forEach(b=>b.onclick=()=>csv('nexura-'+name,head,rows));$$(`[data-print="${name}"]`).forEach(b=>b.onclick=()=>pdf(name,head,rows))}
