function adminTile(){return main('Admin', '', `<div class="panel"><h3>Workspace Backup</h3><p>Export or restore local test records. Import replaces current records.</p><button class="secondary" onclick="document.querySelector('#backup').click()">Export Test Backup</button> <button class="secondary" onclick="document.querySelector('#import').click()">Import v2 Test Backup</button></div><div class="panel"><h3>Promotion Tools</h3><button class="secondary" onclick="document.querySelector('#nx-review-toggle')?.click()">Promotion Review Dashboard</button> <button class="secondary" onclick="document.querySelector('#nx-verification-toggle')?.click()">Criteria Verification + Diary</button></div><div class="panel"><h3>Login Settings</h3><p>Creator setup and local login demonstration. Online authentication and permission enforcement require a server.</p><button class="secondary" onclick="window.nxLogout?.()">Log out</button></div><div class="panel"><h3>Web Login Staff Management</h3><p>Under construction — no staff access controls are enabled yet.</p></div>`)}
