function diary(){const tabsList=["To-Do's","Diary / Tasks","Premium Reminders"];const active=db.tasks.filter(t=>!t.policy&&(tab!==tabsList[0]||(t.status!=='Completed'&&t.due<=now())));const filtered=active.sort((a,b)=>(a.status==='Completed')-(b.status==='Completed')||String(a.due||'9999').localeCompare(String(b.due||'9999')));return main('To-Do\'s/Dairy/Task',`<button class="primary" data-open-task="">+ Add Diary / Task</button>`,tabs(tabsList)+`<div class="panel"><div class="row"><span class="muted">To-Do's: overdue and today’s due or reminder tasks · future planned tasks are in Diary / Tasks</span><span id="taskOpenCount">0 open</span></div><div class="row start"><label style="min-width:240px;flex:1">Live Search <input id="taskSearch" type="search" placeholder="Search title, notes, subtasks, staff, dates, status..."></label><label>Filter <select id="taskFilter"><option>All</option><option>Today</option><option>Upcoming Week</option><option>Custom Dates</option></select></label><label id="taskFromWrap" hidden>From <input type="date" id="taskFrom"></label><label id="taskToWrap" hidden>To <input type="date" id="taskTo"></label></div><div class="row start" style="margin:12px 0;gap:8px"><button type="button" class="secondary small" id="taskCsv">Download CSV</button><button type="button" class="secondary small" id="taskPdf">PDF / Print</button><span class="muted" id="taskCount"></span></div><div id="taskTable">${taskTable(filtered)}</div></div>`)}
