// Read-only task detail first; subtasks remain directly clickable without opening edit form.
function taskView(recordId){
 const r=get('tasks',recordId);if(!r)return;
 const sub=r.subtasks||[];
 const rows=sub.length?sub.map((x,i)=>`<label class="task-check-row"><input type="checkbox" data-subcheck="${i}" ${x.done?'checked':''}><span class="${x.done?'task-done':''}">${esc(x.text)}</span></label>`).join(''):'<p class="muted">No subtasks added.</p>';
 const info=(label,value)=>`<div class="task-info"><strong>${label}</strong><span>${esc(value||'—')}</span></div>`;
 const content=`<div class="task-view">
 ${info('Title',r.title)}<div class="task-subtasks"><strong>Subtasks — tick to complete</strong>${rows}</div>
 ${info('Due Date',r.due)}${info('Reminder Date & Time',r.reminder)}${info('NOTE',r.note)}
 <div class="task-info"><strong>Status</strong><select id="viewTaskStatus">${['Planned','In process','Completed'].map(x=>`<option ${x===r.status?'selected':''}>${x}</option>`).join('')}</select></div>
 <details><summary>Details</summary>${info('Assigned Staff',staffName(r.staff))}${info('Attachment',r.attachmentName||r.attachment)}${r.attachmentId?`<div class="row start"><button class="secondary small" data-file-action="preview">Preview</button><button class="secondary small" data-file-action="download">Download</button><button class="secondary small" data-file-action="share">Share</button><button class="secondary small" data-file-action="delete">Delete</button></div>`:''}${info('Personal Note (private)',r.personalNote)}</details>
 <div class="row start"><button type="button" class="primary" id="editTaskDetails">Edit Task Details</button><button type="button" class="secondary" id="closeTaskView">Close</button></div></div>`;
 $('#modalBody').innerHTML=`<div class="row"><h2>Diary / Task Details</h2><button class="secondary small" id="closeModal">Close</button></div>${content}`;
 $('#modal').classList.remove('hidden');
 $('#closeModal').onclick=closeModal;$('#closeTaskView').onclick=closeModal;
 $('#editTaskDetails').onclick=()=>taskForm(recordId);attachFileButtons('tasks',recordId);
 const refresh=()=>{render();taskView(recordId)};
 $$('[data-subcheck]').forEach(c=>c.onchange=()=>{
   const current=get('tasks',recordId);if(!current)return;
   const subtasks=(current.subtasks||[]).map(x=>({...x}));subtasks[Number(c.dataset.subcheck)].done=c.checked;
   const status=subtasks.length&&subtasks.every(x=>x.done)?'Completed':current.status==='Completed'?'In process':current.status;
   update('tasks',recordId,{subtasks,status});refresh();
 });
 $('#viewTaskStatus').onchange=e=>{update('tasks',recordId,{status:e.target.value});refresh()};
}
function taskForm(recordId=''){
 const r=get('tasks',recordId)||{},sub=r.subtasks||[];
 modal(r.id?'Edit Task':'Add Task',`<div class="grid">
 ${field('title','Title','text','required')}
 <div class="wide"><label>Subtasks</label><div id="subtaskRows"></div><button type="button" class="secondary small" id="addSubtask">+ Add Subtask</button></div>
 ${field('due','Due Date','date')}
 <div><label>Reminder Date/Time</label><div class="row start"><input style="flex:1;min-width:140px" name="reminderDate" type="date"><input style="width:110px" name="reminderTime" type="time" aria-label="Reminder time"></div><small class="muted">Time picker supports AM/PM according to your device settings.</small></div>
 ${note('note','NOTE')}
 ${select('status','Status',['Planned','In process','Completed'].map(x=>option(x,x)).join(''))}
 <details class="wide"><summary>Details</summary>${select('staff','Assigned Staff',staffOptions())}${attachmentControls(r,'task')}${note('personalNote','Personal Note (excluded from reports)')}</details>
 </div>`,async d=>{
  if(!d.title.trim())return false;
  const subtasks=[...document.querySelectorAll('.subtask-row')].map(row=>({text:row.querySelector('input[type=text]').value.trim(),done:row.querySelector('input[type=checkbox]').checked})).filter(x=>x.text);
  d.subtasks=subtasks;
  if(subtasks.length&&subtasks.every(x=>x.done))d.status='Completed';
  if(d.reminderDate&&d.reminderTime)d.reminder=d.reminderDate+'T'+d.reminderTime;
  else d.reminder=d.reminderDate||'';
  delete d.reminderDate;delete d.reminderTime;
  const chosen=$('#recordFile')?.files?.[0];delete d.recordFile;
  const saved=r.id?update('tasks',r.id,d):add('tasks',d);
  if(chosen&&!(await saveRecordAttachment('tasks',saved.id,chosen)))return false;
 });
 const f=$('#editForm');for(const [k,v] of Object.entries(r)){const el=f.elements.namedItem(k);if(el&&typeof v==='string')el.value=v}
 if(r.reminder){const parts=r.reminder.split('T');f.elements.reminderDate.value=parts[0]||'';f.elements.reminderTime.value=parts[1]?.slice(0,5)||''}
 const addRow=(x={text:'',done:false})=>{const el=document.createElement('div');el.className='subtask-row';el.style.cssText='display:flex;gap:8px;align-items:center;margin:7px 0';el.innerHTML=`<input type="checkbox" style="width:22px" ${x.done?'checked':''} aria-label="Subtask complete"><input type="text" placeholder="Subtask" value="${esc(x.text)}" style="flex:1"><button type="button" class="secondary small">Remove</button>`;el.querySelector('button').onclick=()=>el.remove();$('#subtaskRows').append(el)};
 sub.forEach(addRow);$('#addSubtask').onclick=()=>addRow();
 if(r.id)attachFileButtons('tasks',r.id);
}

function codeOrder(a,b){return String(a.code||'').localeCompare(String(b.code||''),undefined,{numeric:true,sensitivity:'base'})}
function hierarchy(parent='',depth=0,seen=new Set()){
 if(depth>20)return '';
 const rank={'Area Manager':0,'Senior Sales Manager':1,'Sales Manager':2,'Sales Representative':3};
 const roots=parent?db.staff.filter(s=>s.manager===parent&&!seen.has(s.id)):db.staff.filter(s=>!s.manager||!db.staff.some(m=>m.id===s.manager));
 return roots.sort((a,b)=>(rank[a.designation]??9)-(rank[b.designation]??9)||codeOrder(a,b)).map(s=>{
 seen.add(s.id);
 return `<div style="margin-left:${Math.min(depth,6)*18}px;padding:9px;border-bottom:1px solid #edf0f4"><button class="link" data-staff-profile="${s.id}">${esc(s.name)} (${esc(s.code)})</button> · ${esc(s.designation)} <button class="secondary small" data-open-staff="${s.id}">Edit</button></div>`+hierarchy(s.id,depth+1,seen)
 }).join('')
}
function hierarchyOrderedStaff(){
 const rank={'Area Manager':0,'Senior Sales Manager':1,'Sales Manager':2,'Sales Representative':3};
 const out=[],seen=new Set();
 function walk(parent){db.staff.filter(s=>s.manager===parent&&!seen.has(s.id)).sort((a,b)=>(rank[a.designation]??9)-(rank[b.designation]??9)||codeOrder(a,b)).forEach(s=>{seen.add(s.id);out.push(s);walk(s.id)})}
 db.staff.filter(s=>!s.manager||!db.staff.some(m=>m.id===s.manager)).sort((a,b)=>(rank[a.designation]??9)-(rank[b.designation]??9)||codeOrder(a,b)).forEach(s=>{if(!seen.has(s.id)){seen.add(s.id);out.push(s);walk(s.id)}});
 db.staff.filter(s=>!seen.has(s.id)).sort(codeOrder).forEach(s=>out.push(s));
 return out;
}
function staff(){const t=['Hierarchy / Transfers','Targets / Performance / Criteria','Attendance and Leaves'];return main('Staff / Team',`<button class="primary" data-open-staff="">+ Add Staff</button>`,tabs(t)+(tab===t[0]?`<div class="panel">${tabs2(['Assign Staff Managers','Transfer / Attachment - De Attachment'])}<div id="staffMove"></div></div>`:tab===t[1]?`<div class="panel">${tabs2(['Criteria','Target'])}<div id="staffTargets"></div></div>`:tab===t[2]?`<div class="panel"><h3>Attendance and Leaves</h3><p class="muted">Reserved for future implementation, as approved. No forms or buttons.</p></div>`:'')+`<div class="panel"><div class="row"><h3>Staff / Team</h3><span class="muted" id="staffCount"></span></div><div class="row start"><label style="flex:1;min-width:200px">Live Search<input id="staffSearch" type="search" placeholder="Name, code, phone, ID, designation..."></label><label>Designation<select id="staffDesignation">${option('','All designations')+designations.map(d=>option(d,d)).join('')}</select></label><label>Manager<select id="staffManager">${staffOptions()}</select></label><label>Expiry From<input id="staffFrom" type="date"></label><label>Expiry To<input id="staffTo" type="date"></label></div><div class="row start" style="margin:12px 0"><button class="secondary small" id="staffCsv">Download CSV</button><button class="secondary small" id="staffPdf">Print / Save PDF</button></div><div id="staffListing"></div></div>`)}
function tabs2(names){return `<div class="tabs">${names.map(n=>`<button data-subtab="${esc(n)}" class="${subtab===n?'active':''}">${esc(n)}</button>`).join('')}</div>`}
function staffForm(recordId=''){const r=get('staff',recordId)||{};modal(r.id?'Edit Staff':'Add Staff',`<div class="grid">${field('name','Name/Father/Spouse Name','text','required')}${field('phone','Phone number (international WhatsApp format)','tel')}${select('designation','Designation',designations.map(x=>option(x,x)).join(''))}${field('code','Code Number','number','required')}<details class="wide" open><summary>Details</summary>${field('nationalId','Registration Number / National ID')}${field('appointment','Date of Appointment','date')}${field('expiryDate','Code / Designation Expiry Date','date')}${attachmentControls(r,'staff')}${note('personalNote','Personal Note (excluded from reports)')}</details></div>`,async d=>{if(db.staff.some(x=>x.code===d.code&&x.id!==r.id)){alert('Code Number must be unique');return false}const chosen=$('#recordFile')?.files?.[0];delete d.recordFile;const saved=r.id?update('staff',r.id,d):add('staff',d);if(chosen&&!(await saveRecordAttachment('staff',saved.id,chosen)))return false;expirySync(saved)});if(r.id)attachFileButtons('staff',r.id);for(const [k,v] of Object.entries(r)){const e=$('#editForm').elements.namedItem(k);if(e&&typeof v==='string')e.value=v}}
function staffProfile(i){const s=get('staff',i);if(!s)return;const policies=db.policies.filter(p=>p.staff===i),target=db.targets.filter(t=>t.staff===i),trans=db.transactions.filter(t=>t.personId===i&&t.personType==='Staff');$('#modalBody').innerHTML=`<div class="row"><h2>${esc(staffName(i))}</h2><button class="secondary" id="closeModal">Close</button></div><p>${esc(s.designation)} · ${esc(s.phone||'')}</p><p><b>Registration Number / National ID:</b> ${esc(s.nationalId||'—')} · <b>Appointment:</b> ${esc(s.appointment||'—')} · <b>Expiry:</b> ${esc(s.expiryDate||'—')}</p>${s.attachmentId?'<h3>Attachment</h3>':''}<p>${esc(s.attachmentName||s.attachment||'No attachment')}</p>${s.attachmentId?'<div class="row start"><button class="secondary small" data-file-action="preview">Preview</button><button class="secondary small" data-file-action="download">Download</button><button class="secondary small" data-file-action="share">Share</button><button class="secondary small" data-file-action="delete">Delete</button></div>':''}<h3>Performance / Targets</h3>${table(['Metric','Target','Achieved'],target,(t)=>`<tr><td>${esc(t.metric)}</td><td>${esc(t.value)}</td><td>${esc(t.achieved||'0')}</td></tr>`)}<h3>Qualification Status</h3><p>${staffQualification(s).promotion.length?'<strong style="color:#14834b">✔ Promotion criteria completed: '+staffQualification(s).promotion.map(c=>esc(c.title||'Untitled')).join(', ')+'</strong>':'Promotion criteria: not yet verified as completed'}</p><p>${staffQualification(s).targets.length?'<strong style="color:#14834b">✔ Targets completed: '+staffQualification(s).targets.map(t=>esc(t.title||'Untitled')).join(', ')+'</strong>':'Assigned targets: not yet verified as completed'}</p><p>Calculated achievements: Fresh ${money(staffQualification(s).ach.fresh)} · Renewal ${money(staffQualification(s).ach.renewal)} · NOP ${staffQualification(s).ach.nop}</p><h3>Historical Performance / Opening Balance</h3>${table(['Type','From','To','Fresh Rs.','Renewal Rs.','NOP','Action'],(db.performanceEntries||[]).filter(e=>e.staff===i && Number((e.cutoff||e.periodStart||'').slice(0,4))>=new Date().getFullYear()-5),e=>`<tr><td>${esc(e.kind)}</td><td>${esc(e.periodStart||'—')}</td><td>${esc(e.cutoff)}</td><td>${money(e.fresh)}</td><td>${money(e.renewal)}</td><td>${esc(e.nop)}</td><td><button class="secondary small" data-profile-edit-performance="${e.id}">Edit</button></td></tr>`)}<h3>Linked Submissions</h3>${table(['Customer','Submission Date','Submission Amount','Policy Status'],db.customers.filter(c=>c.staff===i&&c.submissionChecked),c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.submissionDate)}</td><td>${money(c.submissionAmount)}</td><td>${db.policies.some(p=>p.customer===c.id)?'Issued':'Pending'}</td></tr>`)}<h3>Linked Customers / Clients</h3>${table(['Name/Father/Spouse Name','Address','Phone number','Policy number','Due date'],policies,p=>`<tr><td>${esc(clientName(p.customer))}</td><td>${esc(get('customers',p.customer)?.address)}</td><td>${esc(get('customers',p.customer)?.phone)}</td><td>${esc(p.number)}</td><td>${esc(p.due)}</td></tr>`)}<h3>Finance transactions</h3>${table(['Date','Type','Amount'],trans,t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.type)}</td><td>${money(t.amount)}</td></tr>`)}<button class="primary" id="editProfile">Edit Staff</button> <button class="secondary" id="profilePerformance">+ Add Previous Performance</button>`;$('#modal').classList.remove('hidden');$('#closeModal').onclick=closeModal;attachFileButtons('staff',i);$('#editProfile').onclick=()=>staffForm(i);$('#profilePerformance').onclick=()=>performanceForm(i);$$('[data-profile-edit-performance]').forEach(b=>b.onclick=()=>performanceForm('',b.dataset.profileEditPerformance))}
function descendants(i,seen=new Set()){for(const s of db.staff.filter(x=>x.manager===i&&!seen.has(x.id))){seen.add(s.id);descendants(s.id,seen)}return seen}
function criterionForm(isTarget=false,recordId=''){const collection=isTarget?'targets':'criteria',r=get(collection,recordId)||{};modal((r.id?'Edit ':'Add ')+(isTarget?'Target':'Criteria'),`<div class="grid">${field('title',isTarget?'Target Title / Purpose (e.g. Appreciation Certificate)':'Criteria Title (e.g. Regular / Fast Track / Elite)','text','required')}${badgeColorSelect()}${isTarget?select('staff','Specific Staff (optional)',staffOptions())+select('designation','Or assign to Designation (optional)',option('','Any designation / unassigned')+designations.map(d=>option(d,d)).join('')):select('designation','Designation',designations.map(d=>option(d,d)).join(''))}${field('fresh','Fresh/FYP/New Business (Rs.)','number','min="0" step="any"')}${field('renewal','Renewal Collection (Rs.)','number','min="0" step="any"')}${field('persistency','Persistency %','number','min="0" max="100" step="any"')}${field('nop','Number of Policies NOP','number','min="0"')}${field('start','Duration/ Affiliation period — Start','date')}${field('end','Duration/ Affiliation period — End','date')}<details class="wide"><summary>Previous Years Business Requirements</summary><p class="muted">Add one or more dated performance conditions for the selected designation. Each condition must be met for criteria completion.</p><div id="nx-year-criteria"></div><button type="button" class="secondary small" id="nx-add-year-criterion">+ Add Year / Period</button></details><details class="wide"><summary>Others</summary>${field('juniorsPromotion','Number Of Jonier staff qualifying for promotion to next cadre','number')}${field('juniorsBasic','Number of jonier staff qualifying Annual Basic Quota','number')}${field('juniorsAnnual','Number of jonier staff qualifying Annual promotion quota','number')}</details></div>`,d=>{if(r.id)update(collection,r.id,d);else add(collection,d)});for(const [k,v] of Object.entries(r)){const e=$('#editForm').elements.namedItem(k);if(e&&typeof v==='string')e.value=v}}
function performanceForm(staffId='',entryId=''){db.performanceEntries??=[];const r=get('performanceEntries',entryId)||{};modal(r.id?'Edit Performance':'Add Previous Performance',`<p class="hint">Historical baseline: enter cumulative verified achievements up to the cutoff date. New policy events after that date are tracked separately. Do not enter the same business twice.</p><div class="grid">${select('staff','Staff Member',staffOptions(),'required')}${select('kind','Record Type',option('baseline','Historical opening baseline')+option('adjustment','Manual adjustment (not policy credit)'))}${field('periodStart','Performance Period — From','date','required')}${field('cutoff','Performance Period — To','date','required')}${field('fresh','Fresh/FYP/New Business (Rs.)','number','min="0" step="any"')}${field('renewal','Renewal Collection (Rs.)','number','min="0" step="any"')}${field('nop','Number of Policies NOP','number','min="0"')}${field('persistency','Persistency %','number','min="0" max="100" step="any"')}${note('note','Source / Verification Note')}</div><p class="muted">One historical baseline per staff member. Adjustments are stored separately and are not new policy events.</p>`,d=>{if(!d.staff)return false;if(d.periodStart&&d.cutoff&&d.periodStart>d.cutoff){alert('From date must be on or before To date');return false}if(d.kind==='baseline'&&db.performanceEntries.some(x=>x.staff===d.staff&&x.kind==='baseline'&&x.id!==r.id)){alert('This staff member already has a historical baseline. Edit that baseline instead.');return false}if(r.id)update('performanceEntries',r.id,d);else add('performanceEntries',d)});if(staffId)$('#editForm').elements.staff.value=staffId;for(const [k,v] of Object.entries(r)){const e=$('#editForm').elements.namedItem(k);if(e&&typeof v==='string')e.value=v}if(!r.id)$('#editForm').elements.cutoff.value=now()}
