function customers(){return main('Customers / Clients',`<button class="primary" id="customerAddButton" disabled>+ Add Customer (select representative first)</button>`,`<div class="panel nx-customer-intro"><h3>Customer Journey & Policy Records</h3><p class="muted">Expected Client → Proposal Discussed / Submission → Policy Issued → Policy Records. Existing data and workflow remain unchanged in this redesign trial.</p></div>`+tabs(stages)+`<div class="panel"><div class="row start"><label style="min-width:200px">Sales Representative <select id="customerRep">${staffOptions(s=>s.designation==='Sales Representative')}</select></label><label style="flex:1;min-width:230px">Live Search <input id="clientSearch" type="search" placeholder="Name, phone, address, staff code, policy number..."></label><label>Submission Status<select id="submissionStatus"><option value="">All</option><option value="pending">Pending issuance</option><option value="issued">Issued</option></select></label><label>From Date<input id="clientFrom" type="date"></label><label>To Date<input id="clientTo" type="date"></label></div><div class="row start" style="margin:12px 0"><button class="secondary small" id="clientCsv">Download CSV</button><button class="secondary small" id="clientPdf">Print / Save PDF</button><span class="muted" id="clientCount"></span></div><div id="clientTable"></div></div>`) }
function customerHierarchy(staffId){const chain=[];const seen=new Set();let cur=staffId;while(cur&&!seen.has(cur)){seen.add(cur);const s=get('staff',cur);if(!s)break;chain.push(`${s.name} (${s.code})`);cur=s.manager}return chain.join(' / ')}
function customerDateMatch(date,from,to){return (!from||String(date||'')>=from)&&(!to||String(date||'')<=to)}
function shareClientReport(title,head,rows){const textReport=[title,head.join(' | '),...rows.map(r=>r.join(' | '))].join('\n');if(navigator.share)navigator.share({title,text:textReport}).catch(()=>{});else if(navigator.clipboard?.writeText)navigator.clipboard.writeText(textReport).then(()=>alert('Report copied for sharing.')).catch(()=>alert('Please download CSV to share.'));else alert('Please download CSV to share.')}

function nxPhone(phone){let x=String(phone||'').trim().replace(/[\s().-]/g,'');if(!x)return '';if(/^03\d{9}$/.test(x))return '+92'+x.slice(1);if(/^923\d{9}$/.test(x))return '+'+x;if(/^3\d{9}$/.test(x))return '+92'+x;return x}
function validWhatsapp(phone){return !phone||/^\+[1-9][0-9]{7,14}$/.test(phone.trim())}
function customerForm(recordId='',afterSave=null){const r=get('customers',recordId)||{};const rep=r.staff||selectedClientStaff||$('#customerRep')?.value||'';if(!r.id&&get('staff',rep)?.designation!=='Sales Representative'){alert('Select a Sales Representative before adding a customer.');return}modal(r.id?'Edit Customer':'Expected Client/ Customer',`<div class="grid">${select('staff','Sales Representative (required)',staffOptions(s=>s.designation==='Sales Representative'),'required')}${field('name','Client Full Name','text','required')}${field('guardianName','Father / Spouse / Guardian Name')}${field('phone','Phone (Pakistan or international WhatsApp format)','tel')}${field('address','Address')}${field('meeting','Diary / follow-up / meeting date and time','datetime-local')}${field('occupation','Occupation')}${attachmentControls(r,'task')}</div>`,async d=>{if(get('staff',d.staff)?.designation!=='Sales Representative'){alert('Select a valid Sales Representative');return false}d.phone=nxPhone(d.phone);if(d.phone&&!validWhatsapp(d.phone)){alert('Check phone number: enter 03XXXXXXXXX or +923XXXXXXXXX');return false}const file=$('#recordFile')?.files?.[0];delete d.recordFile;const saved=r.id?update('customers',r.id,d):add('customers',{...d,stage:stages[0],history:[{event:'Expected client created',date:now()}]});if(file&&!(await saveRecordAttachment('customers',saved.id,file)))return false;if(afterSave){selectedClientStaff='';setTimeout(()=>afterSave(saved.id),0)}});if(r.id)attachFileButtons('customers',r.id);$('#editForm').elements.staff.value=rep;for(const [k,v] of Object.entries(r)){const e=$('#editForm').elements.namedItem(k);if(e&&typeof v==='string')e.value=v}}
function logClient(c,event){c.history??=[];c.history.push({event,date:new Date().toISOString()});save()}
function clientProgressForm(i){const c=get('customers',i);if(!c)return;modal('Proposal Discussed / Submission — '+c.name,`<div class="grid"><div class="wide"><label><input type="checkbox" name="proposalChecked" id="proposalChecked" ${c.proposalChecked?'checked':''}> Proposal Discussed</label></div><div id="proposalFields"><h3>Proposed Plan</h3>${field('plan','Plan')}${field('premiums','Number of premiums','number')}${field('amount','Amount of premium (Rs.)','number','min="0" step="any"')}${select('mode','Mode of premium',['Yearly','Half yearly','Quarterly','Monthly'].map(x=>option(x,x)).join(''))}${field('paymentDate','Payment Date','date')}${note('notes','Notes')}</div><div class="wide"><label><input type="checkbox" name="submissionChecked" id="submissionChecked" ${c.submissionChecked?'checked':''}> Submission</label></div><div id="submissionFields">${field('submissionAmount','Submission Amount (Rs.)','number','min="0.01" step="any"')}${field('submissionDate','Submission Date','date')}</div></div><p class="muted">Policy issuance is available only after both steps are completed.</p>`,d=>{const proposal=$('#proposalChecked').checked,submission=$('#submissionChecked').checked;if(submission&&(!d.submissionDate||!(Number(d.submissionAmount)>0))){alert('Submission date and positive amount are required');return false}const beforeP=!!c.proposalChecked,beforeS=!!c.submissionChecked;delete d.proposalChecked;delete d.submissionChecked;update('customers',i,{...d,proposalChecked:proposal,submissionChecked:submission,stage:stages[1]});if(proposal&&!beforeP)logClient(c,'Proposal discussed');if(submission&&!beforeS)logClient(c,'Submission received: Rs. '+d.submissionAmount);if(!submission&&beforeS)logClient(c,'Submission marked pending / unchecked');if(d.paymentDate&&!db.tasks.some(t=>t.customer===i&&t.autoKey==='payment-followup'))add('tasks',{title:'Premium payment follow-up · '+c.name,due:d.paymentDate,status:'Planned',staff:c.staff,customer:i,autoKey:'payment-followup'});});const f=$('#editForm');for(const k of ['plan','premiums','amount','mode','paymentDate','notes','submissionAmount','submissionDate'])if(f.elements[k]&&c[k]!==undefined)f.elements[k].value=c[k];const toggle=()=>{$('#proposalFields').hidden=!$('#proposalChecked').checked;$('#submissionFields').hidden=!$('#submissionChecked').checked};$('#proposalChecked').onchange=toggle;$('#submissionChecked').onchange=toggle;toggle()}

function clientProfile(i){const c=get('customers',i);if(!c)return;const policies=db.policies.filter(p=>p.customer===i),tx=db.transactions.filter(t=>t.personId===i&&t.personType==='Customer');$('#modalBody').innerHTML=`<div class="row"><h2>${esc(c.name)}</h2><button class="secondary" id="closeModal">Close</button></div><p><b>Guardian / Father / Spouse:</b> ${esc(c.guardianName||'—')}</p><p>${esc(c.phone)} · ${esc(c.address)} · ${esc(c.stage)}</p><h3>Client Progress / Plan / Submission</h3><p>Proposal discussed: ${c.proposalChecked?'Yes':'No'} · Submission: ${c.submissionChecked?'Yes':'No'}</p><p>Plan: ${esc(c.plan||'—')} · Premium amount: ${money(c.amount)} · Mode: ${esc(c.mode||'—')} · Payment date: ${esc(c.paymentDate||'—')}</p><p>Submission amount: ${money(c.submissionAmount)} · Submission date: ${esc(c.submissionDate||'—')}</p><h3>Activity History</h3>${table(['Date','Event'],c.history||[],h=>`<tr><td>${esc(h.date)}</td><td>${esc(h.event)}</td></tr>`)}<h3>Attachment</h3><p>${esc(c.attachmentName||c.attachment||'No attachment')}</p>${c.attachmentId?'<div class="row start"><button class="secondary small" data-file-action="preview">Preview</button><button class="secondary small" data-file-action="download">Download</button><button class="secondary small" data-file-action="share">Share</button><button class="secondary small" data-file-action="delete">Delete</button></div>':''}<h3>Policies</h3>${table(['Policy Number','Premium','Risk Date','Due Date'],policies,p=>`<tr><td>${esc(p.number)}</td><td>${money(p.premium)}</td><td>${esc(p.risk)}</td><td>${esc(p.due)}</td></tr>`)}<h3>Finance transactions</h3>${table(['Date','Type','Amount'],tx,t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.type)}</td><td>${money(t.amount)}</td></tr>`)}<button class="primary" id="editClient">Edit Customer</button>`;$('#modal').classList.remove('hidden');$('#closeModal').onclick=closeModal;$('#editClient').onclick=()=>customerForm(i);attachFileButtons('customers',i)}
function policyForm(customerId='',direct=false){const c=get('customers',customerId);modal('Policy Issued — Mandatory Risk Date',`<div class="grid">${select('customer','Customer / Client',clientOptions(),'required')}<div><label>New customer</label><button type="button" class="secondary" id="newPolicyCustomer">+ Add Customer</button></div>${select('staff','Sales Representative',staffOptions(s=>s.designation==='Sales Representative'),'required')}${field('number','Policy Number','text','required')}${field('premium','Premium Amount (Rs.)','number','required min="0.01" step="any"')}${field('due','Due Date','date','required')}${field('risk','Risk Date (manually entered)','date','required')}${select('premiumCategory','Premium Category',[['first','First Year Premium'],['second','Second Year Premium'],['renewal','Renewal Premium']].map(([v,n])=>option(v,n)).join(''))}<h3>Plan / Proposal Details</h3>${field('plan','Plan','text','required')}${field('premiums','Number of premiums','number')}${field('amount','Amount of proposed premium (Rs.)','number','min="0" step="any"')}${select('mode','Mode of premium',['Yearly','Half yearly','Quarterly','Monthly'].map(x=>option(x,x)).join(''))}${field('paymentDate','Payment date','date')}${note('notes','Proposal notes')}</div><p class="hint">Risk Date is always entered manually. First-year, second-year and renewal premiums are recorded separately for reporting.</p>`,d=>{const customer=get('customers',d.customer);if(!customer){alert('Select or add a customer');return false}if(!d.staff||get('staff',d.staff)?.designation!=='Sales Representative'){alert('Select a Sales Representative');return false}if(!d.risk){alert('Risk Date is mandatory');return false}if(db.policies.some(p=>p.number.trim().toLowerCase()===d.number.trim().toLowerCase())){alert('Policy Number already exists');return false}if(c&&!direct&&!(c.proposalChecked&&c.submissionChecked)){alert('Proposal Discussed and Submission must both be checked before issuance');return false}const p=add('policies',{...d,source:c?'workflow':'direct',hierarchySnapshot:customerHierarchy(d.staff)});update('customers',d.customer,{stage:stages[3],plan:d.plan,premiums:d.premiums,amount:d.amount,mode:d.mode,paymentDate:d.paymentDate,notes:d.notes,staff:d.staff});logClient(customer,'Policy issued: '+p.number+' ('+d.premiumCategory+')');if(d.premiumCategory==='first')add('events',{kind:'business',policy:p.id,staff:d.staff,amount:d.premium,risk:d.risk});else add('renewals',{policy:p.id,staff:d.staff,amount:d.premium,date:d.risk,category:d.premiumCategory});/* Reminders now generated on demand by Premium Reminder tab */});const form=$('#editForm');if(c){form.elements.customer.value=c.id;form.elements.staff.value=c.staff||'';for(const k of ['plan','premiums','amount','mode','paymentDate','notes'])if(c[k])form.elements[k].value=c[k]}$('#newPolicyCustomer').onclick=()=>{selectedClientStaff=form.elements.staff.value;if(get('staff',selectedClientStaff)?.designation!=='Sales Representative'){alert('Select a Sales Representative first');return}customerForm('',newId=>policyForm(newId,true))};form.elements.customer.onchange=()=>{const x=get('customers',form.elements.customer.value);if(x){form.elements.staff.value=x.staff||'';for(const k of ['plan','premiums','amount','mode','paymentDate','notes'])if(x[k])form.elements[k].value=x[k]}}}

function schedulePremium(p){const start=new Date(p.due+'T12:00:00');if(Number.isNaN(start.getTime()))return;const months={Yearly:12,'Half yearly':6,Quarterly:3,Monthly:1}[p.mode]||12;const end=new Date(p.risk+'T12:00:00');end.setFullYear(end.getFullYear()+2);for(let date=new Date(start),i=0;date<end&&i<25;i++,date.setMonth(date.getMonth()+months)){const due=date.toISOString().slice(0,10);if(!db.tasks.some(t=>t.policy===p.id&&t.due===due)){add('tasks',{title:'Premium due · '+p.number,due,status:'Planned',staff:p.staff,policy:p.id,reminder:due+'T09:00',note:'Automatic linked policy reminder'})}}}
