function bookBalance(i){const b=get('cashbooks',i);return (Number(b?.opening)||0)+db.transactions.filter(t=>t.book===i).reduce((n,t)=>n+(t.type==='Credit'?1:-1)*Number(t.amount||0),0)}
function bookForm(){modal('Add Cashbook',`<div class="grid">${field('name','Cashbook Name','text','required')}${field('opening','Opening Balance (Rs.)','number','step="any" required')}</div>`,d=>{add('cashbooks',d)})}
function transactionForm(type='Credit'){modal(type+' Transaction',`<div class="grid">${select('book','Cashbook',db.cashbooks.map(b=>option(b.id,b.name)).join(''),'required')}${field('date','Date','date','required')}${select('type','Debit / Credit',option(type,type))}${field('amount','Amount (Rs.)','number','required min="0.01" step="any"')}${select('personType','Account / Person',['Other','Staff','Customer'].map(x=>option(x,x)).join(''))}${select('personId','Linked Staff / Customer',option('','None')+db.staff.map(s=>option(s.id,'Staff · '+s.name)).join('')+db.customers.map(c=>option(c.id,'Customer · '+c.name)).join(''))}${field('personName','Other Person Name')}${note('note','Details / Notes')}${field('attachment','Attachment reference (local test)')}</div>`,d=>{if(!d.book||Number(d.amount)<=0)return false;const linked=get(d.personType==='Staff'?'staff':'customers',d.personId);if(d.personType!=='Other'&&(!linked|| (d.personType==='Staff'&&!db.staff.some(x=>x.id===d.personId))||(d.personType==='Customer'&&!db.customers.some(x=>x.id===d.personId)))){alert('Select a matching linked person');return false}add('transactions',d)});$('#editForm').elements.date.value=now();if(selectedBook)$('#editForm').elements.book.value=selectedBook}
function transferForm(){modal('Transfer Between Cashbooks',`<div class="grid">${select('from','From Cashbook',db.cashbooks.map(b=>option(b.id,b.name)).join(''))}${select('to','To Cashbook',db.cashbooks.map(b=>option(b.id,b.name)).join(''))}${field('date','Date','date','required')}${field('amount','Amount (Rs.)','number','required min="0.01" step="any"')}${note('note','Details / Notes')}</div>`,d=>{if(d.from===d.to){alert('Choose two different cashbooks');return false}const transferId=id();add('transactions',{book:d.from,date:d.date,amount:d.amount,type:'Debit',note:'Transfer out: '+d.note,transferId});add('transactions',{book:d.to,date:d.date,amount:d.amount,type:'Credit',note:'Transfer in: '+d.note,transferId})});$('#editForm').elements.date.value=now()}
