function movementForm(i){const f=get('files',i);if(!f)return;modal('File Movement — '+f.number,`<div class="grid">${select('action','Action',['Issued Out','Returned','Transfer','Archived','Available'].map(x=>option(x,x)).join(''))}${select('staff','Issued To / Transferred To',staffOptions())}${field('issueDate','Issue Date','date')}${field('expected','Expected Return Date','date')}${field('returned','Actual Return Date','date')}${note('note','Movement Notes')}</div>`,d=>{if(d.action==='Issued Out'&&!d.staff){alert('Select Issued To');return false}add('movements',{...d,file:i});update('files',i,{status:d.action==='Transfer'?'Issued Out':d.action})});$('#editForm').elements.issueDate.value=now()}
