const taskExportHead=['Title','Due Date','Reminder Date & Time','Assigned Staff','Phone','Status','NOTE','Subtasks'];
function taskExportRows(arr){return arr.map(t=>[t.title||'',t.due||'',t.reminder||'',get('staff',t.staff)?.name||'',get('staff',t.staff)?.phone||'',t.status||'',t.note||'',(t.subtasks||[]).map(x=>(x.done?'[x] ':'[ ] ')+x.text).join(' | ')])}
function shareTaskReport(arr){const lines=[taskExportHead.join(' | '),...taskExportRows(arr).map(row=>row.join(' | '))];const content=lines.join('\n');if(navigator.share){navigator.share({title:'NEXURA '+tab,text:content}).catch(err=>{if(err.name!=='AbortError')alert('Sharing unavailable: '+err.message)})}else if(navigator.clipboard?.writeText){navigator.clipboard.writeText(content).then(()=>alert('Report copied. Paste it into WhatsApp or email.')).catch(()=>alert('Use CSV download to share this report.'))}else alert('Use CSV download to share this report.')}
const nxTaskFilterState={filter:'All',from:'',to:'',search:''};
function renderTaskFilter(){
 const filter=$('#taskFilter'),search=$('#taskSearch');if(!filter||!search)return;
 filter.value=nxTaskFilterState.filter;
 search.value=nxTaskFilterState.search;
 $('#taskFrom').value=nxTaskFilterState.from;
 $('#taskTo').value=nxTaskFilterState.to;
 const apply=()=>{
  const val=filter.value,from=$('#taskFrom')?.value,to=$('#taskTo')?.value,q=search.value.trim().toLocaleLowerCase();
  $('#taskFromWrap').hidden=val!=='Custom Dates';$('#taskToWrap').hidden=val!=='Custom Dates';
  let arr=db.tasks.filter(t=>!t.policy&&(tab!=="To-Do's"||(t.status!=='Completed'&&((!!t.due&&t.due<=now())||(!!t.reminder&&String(t.reminder).slice(0,10)<=now())))));
  arr=arr.filter(t=>{
   if(val==='Today'&&t.due!==now()&&String(t.reminder||'').slice(0,10)!==now())return false;
   if(val==='Upcoming Week'){const end=new Date();end.setDate(end.getDate()+7);if(!(t.due>=now()&&t.due<=end.toISOString().slice(0,10)))return false}
   if(val==='Custom Dates'&&!((!from||t.due>=from)&&(!to||t.due<=to)))return false;
   if(!q)return true;
   const st=get('staff',t.staff)||{};
   return [JSON.stringify(t),JSON.stringify(st),staffName(t.staff),...(t.subtasks||[]).map(x=>JSON.stringify(x))].join(' ').toLocaleLowerCase().includes(q);
  }).sort((a,b)=>(a.status==='Completed')-(b.status==='Completed')||String(a.due||'9999').localeCompare(String(b.due||'9999')));
  $('#taskTable').innerHTML=taskTable(arr);
  $('#taskCount').textContent=arr.length+' matching record(s)';
  const openCount=document.getElementById('taskOpenCount');if(openCount)openCount.textContent=arr.filter(t=>t.status!=='Completed').length+' open';
  $$('[data-open-task]').forEach(b=>b.onclick=()=>b.dataset.openTask?taskView(b.dataset.openTask):taskForm());
  $$('[data-task-status]').forEach(s=>s.onchange=()=>{update('tasks',s.dataset.taskStatus,{status:s.value});apply()});
  const prefix=tab==="To-Do's"?'nexura-to-dos':'nexura-diary-tasks';
  $('#taskCsv').onclick=()=>csv(prefix,taskExportHead,taskExportRows(arr));
  $('#taskPdf').onclick=()=>pdf(tab,taskExportHead,taskExportRows(arr));

 };
 filter.onchange=()=>{nxTaskFilterState.filter=filter.value;apply()};
 search.oninput=()=>{nxTaskFilterState.search=search.value;apply()};
 $('#taskFrom').onchange=()=>{nxTaskFilterState.from=$('#taskFrom').value;nxTaskFilterState.filter='Custom Dates';filter.value='Custom Dates';apply()};
 $('#taskTo').onchange=()=>{nxTaskFilterState.to=$('#taskTo').value;nxTaskFilterState.filter='Custom Dates';filter.value='Custom Dates';apply()};
 apply();
}

function staffAchievements(staffId){
 const entries=(db.performanceEntries||[]).filter(x=>x.staff===staffId);
 const baseline=entries.find(x=>x.kind==='baseline');
 const cutoff=baseline?.cutoff||'';
 const adjustments=entries.filter(x=>x.kind==='adjustment');
 const liveEvents=new Map();
 for(const e of (db.events||[]))if(e.kind==='business'&&e.staff===staffId&&e.policy&&(!cutoff||e.risk>cutoff)&&get('policies',e.policy)?.source==='issued')liveEvents.set(e.policy,e);
 const sum=(items,k)=>items.reduce((n,x)=>n+(Number(x[k])||0),0);
 return {fresh:(Number(baseline?.fresh)||0)+sum(adjustments,'fresh')+sum([...liveEvents.values()],'amount'),renewal:(Number(baseline?.renewal)||0)+sum(adjustments,'renewal'),nop:(Number(baseline?.nop)||0)+sum(adjustments,'nop')+liveEvents.size,persistency:baseline?.persistency||'',cutoff};
}
function requirementMet(rule,ach){
 const fields=['fresh','renewal','nop','persistency'];let active=false;
 for(const k of fields){if(rule[k]!==''&&rule[k]!=null&&Number(rule[k])>0){active=true;if(Number(ach[k])<Number(rule[k]))return false}}
 // Criteria with duration/team-qualification requirements require separate verified data; never mark prematurely.
 if(['juniorsPromotion','juniorsBasic','juniorsAnnual'].some(k=>Number(rule[k])>0))return false;
 if(rule.start&&now()<rule.start)return false;
 if(rule.end&&now()>rule.end)return false;
 return active;
}
function staffQualification(staff){const ach=staffAchievements(staff.id);return {
 promotion:(db.criteria||[]).filter(c=>c.designation===staff.designation&&requirementMet(c,ach)),
 targets:(db.targets||[]).filter(t=>(t.staff===staff.id||(!t.staff&&t.designation===staff.designation))&&requirementMet(t,ach)),ach};}
