function renderCustomers(){if(tile!==2)return;const rep=$('#customerRep'),search=$('#clientSearch'),from=$('#clientFrom'),to=$('#clientTo'),status=$('#submissionStatus');const addButton=$('#customerAddButton');addButton.onclick=()=>customerForm();const draw=()=>{addButton.disabled=!rep.value;addButton.textContent=rep.value?'+ Add Customer':'+ Add Customer (select representative first)';const q=search.value.trim().toLowerCase(),r=rep.value,f=from.value,t=to.value,issued=tab===stages[2]||tab===stages[3];let head=[],data=[],arr=[];if(issued){arr=db.policies.filter(p=>(tab===stages[2]?!p.archived:p.archived)&&(!r||p.staff===r)&&customerDateMatch(p.risk,f,t)&&(JSON.stringify(p)+' '+JSON.stringify(get('customers',p.customer)||{})+' '+customerHierarchy(p.staff)).toLowerCase().includes(q));head=['Name/Father/Spouse Name','Phone','Policy Number','Premium Rs','Premium Category','Risk Date','Due Date','Address','Complete Hierarchy'];data=arr.map(p=>[clientName(p.customer),get('customers',p.customer)?.phone,p.number,p.premium,p.premiumCategory||'first',p.risk,p.due,get('customers',p.customer)?.address,customerHierarchy(p.staff)]);$('#clientTable').innerHTML=`<div class="row start"><button class="primary" id="directPolicy">+ Direct Policy Entry</button></div>`+table([...head,'Profile'],arr,p=>`<tr><td><button class="link" data-client-profile="${esc(p.customer)}">${esc(clientName(p.customer))}</button></td><td>${esc(get('customers',p.customer)?.phone)}</td><td>${esc(p.number)}</td><td>${money(p.premium)}</td><td>${esc(p.premiumCategory||'first')}</td><td>${esc(p.risk)}</td><td>${esc(p.due)}</td><td>${esc(get('customers',p.customer)?.address)}</td><td>${esc(customerHierarchy(p.staff))}</td><td><button class="secondary small" data-client-profile="${esc(p.customer)}">View</button></td></tr>`);$('#directPolicy').onclick=()=>policyForm()}else{arr=db.customers.filter(c=>c.stage===tab&&(!r||c.staff===r)&&customerDateMatch(tab===stages[1]?c.submissionDate||c.createdAt?.slice(0,10):c.meeting?.slice(0,10)||c.createdAt?.slice(0,10),f,t)&&(!status.value||(status.value==='pending'?!db.policies.some(p=>p.customer===c.id):db.policies.some(p=>p.customer===c.id)))&&(JSON.stringify(c)+' '+staffName(c.staff)+' '+customerHierarchy(c.staff)).toLowerCase().includes(q));head=['Name/Father/Spouse Name','Phone','Address','Meeting / Follow-up','Sales Representative','Proposal','Submission Amount','Submission Date','Submission Status'];data=arr.map(c=>[c.name,c.phone,c.address,c.meeting,staffName(c.staff),c.proposalChecked?'Discussed':'Pending',c.submissionAmount,c.submissionDate,c.submissionChecked?'Submitted — Pending Policy':'Not submitted']);$('#clientTable').innerHTML=table([...head,'Actions'],arr,c=>`<tr><td><button class="link" data-client-profile="${esc(c.id)}">${esc(c.name)}</button></td><td>${esc(c.phone)}</td><td>${esc(c.address)}</td><td>${esc(c.meeting||'—')}</td><td>${esc(staffName(c.staff))}</td><td>${c.proposalChecked?'✔ Discussed':'Pending'}</td><td>${money(c.submissionAmount)}</td><td>${esc(c.submissionDate||'—')}</td><td>${c.submissionChecked?'Submitted / Policy pending':'Not submitted'}</td><td><button class="secondary small" data-progress="${esc(c.id)}">${c.stage===stages[0]?'Proceed ⏩':'Manage / Issue'}</button> <button class="secondary small" data-client-profile="${esc(c.id)}">Profile</button></td></tr>`);$$('[data-progress]').forEach(b=>b.onclick=()=>progressCustomer(b.dataset.progress))}$$('[data-client-profile]').forEach(b=>b.onclick=()=>clientProfile(b.dataset.clientProfile));$('#clientCount').textContent=`${arr.length} record(s) · ${tab}`;$('#clientCsv').onclick=()=>csv('nexura-clients-'+tab.replace(/[^a-z]+/gi,'-'),head,data);$('#clientPdf').onclick=()=>pdf('Customers / Clients — '+tab,head,data)};[rep,search,from,to,status].forEach(el=>{el.oninput=draw;el.onchange=draw});draw()}
